      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00104",
          "explanation": "The doctor required formal discharge orders for medication name, dose, and frequency.",
          "quote": "准确药名、准确剂量、准确频次"
        },
        {
          "event_id": "lite_evt_00130",
          "explanation": "The doctor identified the responsible clinical owner for medication clarification.",
          "quote": "第一顺位先找管床医生"
        }
      ],
      "explanation": "The doctor separated anticoagulant from analgesic/anti-inflammatory medication risk and instructed the family not to guess, but to obtain written clarification from the ward team before administering unclear medications.",
